1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	
4	interface CliRun {
5	  stdout: string;
6	  stderr: string;
7	  code: number;
8	}
9	
10	const runCli = (input: string): Promise<CliRun> =>
11	  new Promise((resolve, reject) => {
12	    const child = spawn("node_modules/.bin/tsx", ["src/cli.ts"]);
13	    let stdout = "";
14	    let stderr = "";
15	    child.stdout.on("data", (chunk) => (stdout += chunk));
16	    child.stderr.on("data", (chunk) => (stderr += chunk));
17	    child.on("error", reject);
18	    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
19	    child.stdin.end(input);
20	  });
21	
22	// A clean rejection is one fact spelled four ways: nothing on stdout, a
23	// non-zero code, and a stderr that explains the cause without a stack trace.
24	// Naming it keeps the four from reading as four unrelated claims.
25	const expectCleanRejection = (run: CliRun, cause: string): void => {
26	  expect(run.code).not.toBe(0);
27	  expect(run.stdout).toBe("");
28	  expect(run.stderr).toContain(cause);
29	  expect(run.stderr).not.toContain("at ");
30	};
